import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const dispelPhysicalScenarios=['dispel-two','dispel-mixed','dispel-zero','dispel-empty','dispel-multi-b','dispel-multi-c','dispel-fate','dispel-parent-cancel','dispel-attack-fate','dispel-decline','dispel-cost','dispel-hand','dispel-defense'] as const;
export type DispelPhysicalScenario=typeof dispelPhysicalScenarios[number];
export function isDispelPhysicalScenario(name:string):name is DispelPhysicalScenario{return (dispelPhysicalScenarios as readonly string[]).includes(name);}
export function dispelMode(name:DispelPhysicalScenario){const multi=name==='dispel-multi-b'||name==='dispel-multi-c',cost=name==='dispel-cost';return {multi,cost,defense:name==='dispel-defense',target:name==='dispel-multi-c'?2:1,attack:multi?'a2-p10-r2c1':cost?'a2-p09-r2c1':'a2-p24-r1c2',bFollowers:name==='dispel-two'?['a2-p19-r2c3','a2-p20-r2c3']:name==='dispel-mixed'?['a2-p19-r2c3','a2-p20-r2c3','a2-p20-r3c1']:name==='dispel-empty'?[]:name==='dispel-zero'||name==='dispel-hand'?['a2-p20-r3c1']:['a2-p19-r2c3','a2-p20-r3c1'],cFollowers:multi?['a2-p20-r2c3','a2-p22-r1c1']:['a2-p22-r1c1']};}
/** Actual setup placement, optional Blessing OPEN to permit3 followers, and prior CHANT/fullturns. */
export function makeDispelPhysicalScenario(name:DispelPhysicalScenario,players:{id:string;name:string}[]){
 const m=dispelMode(name);let s=createGame(players,entropy(),{startingSeat:m.defense?1:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.cost?'黒騎士ガーウィン':'侍大将のシン','魔導王ガイナス','忍びのイダ','占星術師のアルセイル'][i]!);for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};
 const keep=[takeCard(s,m.defense?b:a,m.attack),takeCard(s,a,'a2-p02-r3c1'),takeCard(s,a,'a2-p24-r1c3'),takeCard(s,b,'a2-p02-r2c2'),takeCard(s,d,'a2-p02-r2c3'),...m.bFollowers.map(id=>takeCard(s,b,id)),...m.cFollowers.map(id=>takeCard(s,c,id))];if(name==='dispel-hand')keep.push(takeCard(s,b,'a2-p19-r2c3'),takeCard(s,b,'a2-p20-r2c3'));for(const p of players)trimHand(s,p.id,...keep);let blessing:string|undefined;if(name==='dispel-mixed'){blessing=takeCard(s,b,'a2-p01-r2c1');s.players[b]!.hand=s.players[b]!.hand.filter(id=>id!==blessing);}const ordinary=s.deck.filter(id=>getAction(id)!.category!=='open'),opens=s.deck.filter(id=>getAction(id)!.category==='open');s.deck=blessing?[blessing,...ordinary,...opens]:[...ordinary,...opens];s.events=[];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e=entropy(),r=transition(s,input,e);if(!r.ok)throw Error(`DISPEL_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('DISPEL_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('DISPEL_FIXTURE_CARDS');}
 function settle(){for(let n=0;n<300;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('DISPEL_FIXTURE_WINDOW');}
 function start(id:string){act(id,{type:'START_TURN'});settle();act(id,{type:'CHOOSE_DRAW',draw:false});settle();}
 function end(id:string){if(s.phase==='action')act(id,{type:'PASS_ACTION'});if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>!keep.includes(x)).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});settle();}
 for(const id of [a,b,c,d]){for(const cardInstanceId of (id===b?m.bFollowers:id===c?m.cFollowers:[]).slice(0,2))act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId});act(id,{type:'PASS_SETUP'});}
 // The blessing arrives with the round-end refill, so the third follower goes down in the next round (G10).
 for(const cardInstanceId of m.bFollowers.slice(2))act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId});for(const cardInstanceId of m.cFollowers.slice(2))act(c,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId});readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));if(blessing&&!s.players[b]!.open.includes(blessing))throw Error('DISPEL_FIXTURE_BLESSING');start(m.defense?b:a);if(m.multi){act(a,{type:'CHANT',cardInstanceId:m.attack});end(a);for(const id of [b,c,d]){start(id);end(id);}start(a);}return s;
}
